function solar(tMs){
  const n = (tMs - Date.UTC(2000,0,1,12))/86400000;
  const T = n/36525;
  const L = ((280.460 + 0.9856474*n) % 360 + 360) % 360;
  const g = (357.528 + 0.9856003*n)*DEG;
  const lam = (L + 1.915*Math.sin(g) + 0.020*Math.sin(2*g))*DEG;
  const eps = (23.439 - 0.0000004*n)*DEG;
  const decl = Math.asin(Math.sin(eps)*Math.sin(lam))/DEG;
  const ra = Math.atan2(Math.cos(eps)*Math.sin(lam), Math.cos(lam))/DEG;
  let gmst = (280.46061837 + 360.98564736629*n + 0.000387933*T*T - T*T*T/38710000) % 360;
  if (gmst < 0) gmst += 360;
  let subLon = (ra - gmst) % 360;
  subLon = ((subLon + 540) % 360) - 180;
  return { decl, subLon, gmst };
}
```

ecef:
```js
function ecef(lat, lon, r, out){
  const cl = Math.cos(lat);
  out.x = r*cl*Math.cos(lon);
  out.y = r*Math.sin(lat);
  out.z = -r*cl*Math.sin(lon);
  return out;
}
function fromEcef(v){
  const r = v.length();
  return { lat: Math.asin(THREE.MathUtils.clamp(v.y/r,-1,1))/DEG, lon: Math.atan2(-v.z, v.x)/DEG };
}
```

