let eqx = null, eqxAt = 0;
function getEquinox(){
  const now = Date.now();
  if (eqx && now - eqxAt < 60000) return eqx;
  eqxAt = now;
  let prev = solarDecl... use solar(now).decl;
  for (let h=1; h<=9600; h++){
    const d1 = solar(now + h*3600e3).decl;
    if (Math.sign(d1) !== Math.sign(prev) && d1 !== 0){
      const when = now + h*3600e3;
      eqx = { when, type: prev>0?'AUTUMNAL':'VERNAL' };
      return eqx;
    }
    prev = d1;
  }
  eqx = null; return null;
}
