Ephemeralis:
```js
function solarEphemeris(tMs) {
  const n = (tMs - Date.UTC(2000, 0, 1, 12)) / 86400000;
  const L = (280.460 + 0.9856474 * n) % 360;
  const g = (357.528 + 0.9856003 * n) * DEG;
  const lambda = (L + 1.915 * Math.sin(g) + 0.020 * Math.sin(2*g)) * DEG;
  const eps = (23.439 - 4e-9 * n) * DEG;
  const decl = Math.asin(Math.sin(eps) * Math.sin(lambda)) / DEG;
  const RA = Math.atan2(Math.cos(eps) * Math.sin(lambda), Math.cos(lambda)) / DEG;
  const T = n / 36525;
  let gmst = (280.46061837 + 360.98564736629 * n + 0.000387933 * T * T - T * T * T / 38710000) % 360;
  if (gmst < 0) gmst += 360;
  let subLon = RA - gmst;
  subLon = ((subLon + 540) % 360) - 180;
  return { decl, subLon, gmst };
}
```

ECEF:
```js
function ecef(latDeg, lonDeg, r, out) {
  const lat = latDeg * DEG, lon = lonDeg * DEG;
  out.set(r * Math.cos(lat) * Math.cos(lon), r * Math.sin(lat), -r * Math.cos(lat) * Math.sin(lon));
  return out;
}
function latLonFromVec(v) {
  const r = v.length();
  return [Math.asin(v.y / r) / DEG, Math.atan2(-v.z, v.x) / DEG];
}
```

