```glsl
uniform sampler2D dayMap, nightMap, waterMap, cloudMap;
uniform vec3 sunDir;
uniform vec3 issDir;
uniform float time;
uniform float glowOn;
varying vec2 vUv; varying vec3 vNormalW; varying vec3 vPosW;

void main() {
  vec3 N = normalize(vNormalW);
  vec3 V = normalize(cameraPosition - vPosW);
  float nds = dot(N, sunDir);
  float dayAmt = smoothstep(-0.055, 0.165, nds);
  vec3 day = texture2D(dayMap, vUv).rgb;
  vec3 night = texture2D(nightMap, vUv).rgb;
  vec3 col = day * (0.24 + 1.08 * clamp(nds, 0.0, 1.0));
  vec3 H = normalize(sunDir + V);
  float spec = pow(max(dot(N, H), 0.0), 64.0) + 0.18 * pow(max(dot(N, H), 0.0), 8.0);
  float water = texture2D(waterMap, vUv).r;
  col += vec3(1.05, 0.85, 0.6) * 1.1 * spec * water * dayAmt;
  col = mix(col, night * vec3(3.1, 2.75, 2.25), 1.0 - dayAmt);
  vec2 cuv = vec2(fract(vUv.x + time * 1.1e-6), vUv.y);
  float ca = texture2D(cloudMap, cuv).a;
  col = mix(col, col * 0.78, ca * 0.55 * dayAmt);
  float ang = acos(clamp(dot(N, issDir), -1.0, 1.0));
  float glow = exp(-165.0 * ang * ang) + 0.22 * exp(-14.0 * ang * ang);
  col += vec3(0.35, 0.85, 1.0) * glow * glowOn * (0.5 + 1.1 * (1.0 - dayAmt)) * 1.2;
  float fres = pow(1.0 - max(dot(N, V), 0.0), 3.2);
  col += vec3(0.22, 0.48, 1.0) * fres * (0.10 + 0.55 * smoothstep(-0.4, 0.55, nds));
  gl_FragColor = vec4(col, 1.0);
}
```

