trailCount = 0;
function pushTrail(p) {
  if (trailCount > 0) {
    const li = (trailCount - 1) * 3;
    const dx = p.x - trailPos[li], dy = p.y - trailPos[li+1], dz = p.z - trailPos[li+2];
    if (dx*dx + dy*dy + dz*dz < 0.0225) return;
  }
  if (trailCount === TRAIL_MAX) {
    trailPos.copyWithin(0, 3);
    trailCount--;
  }
  const i = trailCount * 3;
  trailPos[i] = p.x; trailPos[i+1] = p.y; trailPos[i+2] = p.z;
  trailCount++;
  // colors
  for (let k = 0; k < trailCount; k++) {
    const f = Math.pow((k + 1) / trailCount, 1.6);
    const ci = k * 3;
    trailCol[ci] = 0.30 * f; trailCol[ci+1] = 0.80 * f; trailCol[ci+2] = 1.0 * f;
  }
  trailGeo.attributes.position.needsUpdate = true;
  trailGeo.attributes.color.needsUpdate = true;
  trailGeo.setDrawRange(0, trailCount);
}
