    const ctrl = new AbortController();
    const to = setTimeout(() => ctrl.abort(), 4500);
    const res = await fetch(`https://api.wheretheiss.at/v1/satellites/${ISS_ID}`, { signal: ctrl.signal });
    clearTimeout(to);
    if (!res.ok) throw new Error(res.status);
    const d = await res.json();
    const fix = {
      lat: d.latitude, lon: d.longitude, alt: d.altitude, vel: d.velocity,
      vis: d.visibility, tMs: d.timestamp * 1000
    };
    onFix(fix);
  } catch (e) { /* ignore; status handles */ }
}
