let equiCache = { t: 0, declNow: 0, next: null };
function equinoxInfo() {
  const now = performance.now();
  if (equiCache.next && now - equiCache.t < 60000) return equiCache.next;
  const t0 = Date.now();
  let prev = solarEphemeris(t0).decl;
  for (let h = 1; h <= 9600; h++) {
    const d = solarEphemeris(t0 + h * 3600000).decl;
    if ((prev > 0 && d <= 0) || (prev <= 0 && d > 0)) {
      const ms = t0 + h * 3600000;
      const type = prev > 0 ? 'AUTUMNAL' : 'VERNAL';
      equiCache = { t: now, next: { type, ms } };
      return equiCache.next;
    }
    prev = d;
  }
  equiCache = { t: now, next: null };
  return null;
}
