```js
function updateShade(decl, subLon) {
  const sl = subLon * DEG, sd = decl * DEG;
  const sinSL = Math.sin(sl), cosSL = Math.cos(sl), sinL = Math.sin(sd), cosL = Math.cos(sd);
  const data = shadeImage.data;
  for (let y = 0; y < 180; y++) {
    const lat = (90 - (y + 0.5) * (180/180)) * DEG; // y row → lat
    const sinLat = Math.sin(lat), cosLat = Math.cos(lat);
    for (let x = 0; x < 360; x++) {
      const lon = (x * (360/360) - 180) * DEG;
      const dot = sinSL * sinLat + cosSL * cosLat * Math.cos(lon - sl);
      let a = (0.015 - dot) / 0.28;
      a = Math.min(1, Math.max(0, a)) * 0.82;
      const i = (y * 360 + x) * 4;
      const li = i * 3; // careful with index
      const nR = nightL[li], nG = nightL[li+1], nB = nightL[li+2];
      data[i]   = 6 * (1 - a) + nR * 1.4 * a;
      data[i+1] = 9 * (1 - a) + nG * 1.4 * a;
      data[i+2] = 20 * (1 - a) + nB * 1.4 * a;
      data[i+3] = 255;
    }
  }
  mapShadeCtx.putImageData(shadeImage, 0, 0);
}
